steps.check:
def answers():
    rows = [[101, "민준", 17, "yoga"], [102, "서연", 24, "swim"], [103, "도윤", 31, "yoga"], [104, "하은", 20, "yoga"], [105, "지호", 45, "swim"], [106, "수아", 52, "yoga"]]
    return [sum(1 for r in rows if r[2] >= 20 and r[3] == 'yoga')]

def answers():
    form = {'table': '정형', 'json': '반정형', 'text': '비정형', 'video': '비정형'}
